<?php
use Eventify\Domain\AdminInput;
use Eventify\Security\Session;
$escape = static fn (mixed $value): string => htmlspecialchars(is_string($value) || is_numeric($value) ? (string) $value : '', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$value = static fn (string $key, string $default = ''): string => $escape($values[$key] ?? $default);
$date = static fn (string $start): string => (new DateTimeImmutable($start, new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('America/Costa_Rica'))->format('d/m/Y H:i');
$csrf = Session::token();
$title = match ($view) { 'users' => 'Usuarios', 'user-promotion' => 'Autorizar administrador', 'reservations' => 'Reservas', 'reservation' => 'Detalle de reserva', 'categories' => 'Categorías', 'category' => 'Editar categoría', 'events' => 'Eventos', 'event' => $record === null ? 'Crear evento' : 'Detalle y edición del evento', default => 'Administración' };
$terminal = $record !== null && isset($record['status']) && in_array($record['status'], ['CANCELADO', 'FINALIZADO'], true);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $escape($title) ?> · Eventify</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="icon" href="/assets/icon.svg"><script src="/assets/js/ui.js" defer></script></head>
<body><header class="site-header"><a class="brand" href="/">eventify<span>.</span></a><nav aria-label="Administración"><a href="/admin">Administración</a><a href="/admin/categorias">Categorías</a><a href="/admin/eventos">Eventos</a><a href="/admin/reservas">Reservas</a><a href="/admin/usuarios">Usuarios</a><a href="/cuenta">Mi cuenta</a></nav></header>
<main class="events-main"><p class="eyebrow">Administración de Eventify</p><h1 class="page-title"><?= $escape($title) ?></h1>
<?php if ($errors !== []): ?><div class="form-errors" role="alert"><?php foreach ($errors as $error): ?><p><?= $escape($error) ?></p><?php endforeach; ?></div><?php endif; ?>
<?php if (($_GET['guardado'] ?? '') === 'ok'): ?><p class="notice" role="status">Cambios guardados correctamente.</p><?php endif; ?>
<?php if ($view === 'home'): ?>
<?php require PROJECT_ROOT . '/app/Views/admin-dashboard.php'; ?>
<div class="event-grid"><article class="event-card"><h2>Usuarios</h2><p>Busque una cuenta y autorice a las personas que administrarán Eventify.</p><a class="return-link" href="/admin/usuarios">Gestionar usuarios</a></article><article class="event-card"><h2>Categorías</h2><p>Organice las experiencias y gestione las categorías activas.</p><a class="return-link" href="/admin/categorias">Gestionar categorías</a></article><article class="event-card"><h2>Eventos</h2><p>Cree experiencias, actualice sus datos y gestione su publicación.</p><a class="return-link" href="/admin/eventos">Gestionar eventos</a></article></div>
<?php elseif (in_array($view, ['users', 'user-promotion'], true)): ?>
<?php require PROJECT_ROOT . '/app/Views/admin-users.php'; ?>
<?php elseif (in_array($view, ['reservations', 'reservation'], true)): ?>
<?php require PROJECT_ROOT . '/app/Views/admin-reservations.php'; ?>
<?php elseif (in_array($view, ['categories', 'category'], true)): ?>
<section class="admin-form-card"><h2><?= $view === 'categories' ? 'Crear categoría' : 'Datos de la categoría' ?></h2><form method="post" class="admin-form">
<input type="hidden" name="csrf" value="<?= $csrf ?>"><div><label for="category-name">Nombre</label><input id="category-name" name="name" maxlength="120" value="<?= $value('name') ?>" required></div><div><label for="category-slug">Identificador</label><input id="category-slug" name="slug" maxlength="120" pattern="[a-z0-9]+(-[a-z0-9]+)*" value="<?= $value('slug') ?>" required><p class="field-help">Ejemplo: gastronomia. Minúsculas, números y guiones.</p></div><div><label for="category-active">Estado</label><select id="category-active" name="is_active"><option value="1" <?= ($values['is_active'] ?? 1) == 1 ? 'selected' : '' ?>>Activa</option><option value="0" <?= ($values['is_active'] ?? 1) == 0 ? 'selected' : '' ?>>Inactiva</option></select></div><button class="button" type="submit">Guardar categoría</button></form><p class="field-help">Desactivar conserva los eventos y su historial. La categoría deja de ofrecerse para eventos nuevos.</p></section>
<?php if ($view === 'categories'): ?><div class="event-grid admin-list"><?php foreach ($rows as $item): ?><article class="event-card"><h2><?= $escape($item['name']) ?></h2><p><?= $item['is_active'] ? 'Activa' : 'Inactiva' ?></p><a href="/admin/categorias/<?= (int) $item['id'] ?>/editar">Editar categoría</a></article><?php endforeach; ?></div><?php endif; ?>
<?php elseif ($view === 'events'): ?>
<a class="return-link" href="/admin/eventos/nuevo">Crear evento</a><div class="event-grid admin-list"><?php foreach ($rows as $item): ?><article class="event-card"><h2><?= $escape($item['name']) ?></h2><p><?= $escape($item['category']) ?> · <?= $escape($item['status']) ?></p><p><?= $date($item['starts_at']) ?> (Costa Rica)</p><p><?= Eventify\Support\Format::money($item['price']) ?> · Capacidad <?= (int) $item['capacity'] ?></p><a href="/admin/eventos/<?= (int) $item['id'] ?>/editar">Consultar y editar</a></article><?php endforeach; ?></div>
<?php else: ?>
<?php if ($terminal): ?><p class="notice">Evento <?= $escape($record['status']) ?>. Se conserva su información y su historial.</p><?php endif; ?>
<section class="admin-form-card"><form method="post" action="<?= $record === null ? '/admin/eventos/nuevo' : '/admin/eventos/' . (int) $record['id'] . '/editar' ?>" class="admin-form"><input type="hidden" name="csrf" value="<?= $csrf ?>"><fieldset <?= $terminal ? 'disabled' : '' ?>><legend>Datos de la experiencia</legend>
<div><label for="event-name">Nombre</label><input id="event-name" name="name" maxlength="180" value="<?= $value('name') ?>" required></div><div><label for="event-slug">Identificador del enlace</label><input id="event-slug" name="slug" maxlength="160" pattern="[a-z0-9]+(-[a-z0-9]+)*" value="<?= $value('slug') ?>" <?= $record !== null ? 'readonly' : '' ?> required><p class="field-help">Se conserva después de crear el evento. Ejemplo: taller-de-cocina.</p></div>
<div class="form-wide"><label for="event-description">Descripción</label><textarea id="event-description" name="description" maxlength="10000" rows="5" required><?= $value('description') ?></textarea></div>
<div><label for="event-category">Categoría</label><select id="event-category" name="category_id" required><option value="">Seleccione</option><?php foreach ($categories as $category): ?><?php if ($category['is_active'] || (int) ($record['category_id'] ?? 0) === (int) $category['id']): ?><option value="<?= (int) $category['id'] ?>" <?= (string) ($values['category_id'] ?? '') === (string) $category['id'] ? 'selected' : '' ?>><?= $escape($category['name']) ?><?= $category['is_active'] ? '' : ' (inactiva)' ?></option><?php endif; ?><?php endforeach; ?></select></div>
<div><label for="event-image">Imagen</label><select id="event-image" name="image_path" required><?php foreach (AdminInput::IMAGES as $path => $label): ?><option value="<?= $escape($path) ?>" <?= ($values['image_path'] ?? '/assets/icon.svg') === $path ? 'selected' : '' ?>><?= $escape($label) ?></option><?php endforeach; ?></select></div>
<?php $startValue = $values['starts_at'] ?? ''; if (is_string($startValue) && preg_match('/\A[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\z/', $startValue)) { $startValue = (new DateTimeImmutable($startValue, new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('America/Costa_Rica'))->format('Y-m-d\TH:i:s'); } ?>
<div><label for="event-start">Fecha y hora (Costa Rica)</label><input id="event-start" name="starts_at" type="datetime-local" step="1" min="2000-01-01T00:00" max="2099-12-31T23:59:59" value="<?= $escape($startValue) ?>" required><p class="field-help">Los eventos con reservas conservan su fecha.</p></div>
<div><label for="event-location">Ubicación</label><input id="event-location" name="location" maxlength="255" value="<?= $value('location') ?>" required></div><div><label for="event-capacity">Capacidad</label><input id="event-capacity" name="capacity" type="number" min="1" max="4294967295" step="1" value="<?= $value('capacity') ?>" required></div><div><label for="event-price">Precio en colones</label><input id="event-price" name="price" inputmode="decimal" value="<?= $value('price', '0.00') ?>" required><p class="field-help">Sin separadores de miles; dos decimales como máximo. Precio cero permitido.</p></div>
<div><label for="event-latitude">Latitud (opcional)</label><input id="event-latitude" name="latitude" inputmode="decimal" value="<?= $value('latitude') ?>"></div><div><label for="event-longitude">Longitud (opcional)</label><input id="event-longitude" name="longitude" inputmode="decimal" value="<?= $value('longitude') ?>"><p class="field-help">Complete ambas coordenadas para consultar el clima.</p></div>
<div><label for="event-status">Estado</label><select id="event-status" name="status"><?php foreach (['BORRADOR', 'PUBLICADO'] as $state): ?><option value="<?= $state ?>" <?= ($values['status'] ?? 'BORRADOR') === $state ? 'selected' : '' ?>><?= $state ?></option><?php endforeach; ?><?php if ($terminal): ?><option selected><?= $escape($record['status']) ?></option><?php endif; ?></select></div><button class="button" type="submit">Guardar evento</button></fieldset></form></section>
<?php if ($record !== null && !$terminal): ?><section class="admin-form-card"><h2>Estado del evento</h2><p>Cancelar impide nuevas reservas y conserva las existentes. Finalizar solo se permite cuando el inicio ya ocurrió.</p><form class="state-form" method="post" action="/admin/eventos/<?= (int) $record['id'] ?>/estado"><input type="hidden" name="csrf" value="<?= $csrf ?>"><label for="event-transition">Acción</label><select id="event-transition" name="status"><option value="CANCELADO">Cancelar evento y conservar historial</option><option value="FINALIZADO">Marcar como finalizado</option></select><button class="button" type="submit">Aplicar cambio de estado</button></form></section><?php endif; ?>
<?php endif; ?>
<?php if (in_array($view, ['categories', 'events'], true)): ?><?php if ($rows === []): ?><p class="notice">No hay registros en esta página.</p><?php endif; ?><nav class="catalog-pagination" aria-label="Páginas de administración"><?php if ($number > 1): ?><a href="?page=<?= $number - 1 ?>">Anterior</a><?php endif; ?><span>Página <?= $number ?></span><?php if ($hasMore): ?><a href="?page=<?= $number + 1 ?>">Siguiente</a><?php endif; ?></nav><?php endif; ?>
</main><footer>Eventify · Experiencias y eventos</footer></body></html>
